  }).listen(4444, function () {
    var success = false, failure = false, error;

    axios.get('http://localhost:4444/one', {
      maxContentLength: 2000
    }).then(function (res) {
      success = true;
    }).catch(function (err) {
      error = err;
      failure = true;
    });

